import {record,parse,analyze,split,bundle,zip} from './dataset-core.js';
const $=s=>document.querySelector(s),key='tiny-dataset-studio-v1';let rows=[],editing=null,undo=null,page=0,settings={validation:10,test:10,seed:'tiny-1'};
const status=text=>$('#studio-status').textContent=text;
try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved){rows=saved.records.map(record);settings={...settings,...saved.settings};}}catch{status('Saved data could not be restored. Import a project backup to recover it.');}
for(const k of ['validation','test','seed'])$('#'+k).value=settings[k];
function persist(){try{localStorage.setItem(key,JSON.stringify({version:1,records:rows,settings}));}catch{status('Browser storage is unavailable or full. Use Save project to keep your work.');}}
function snapshot(){undo={rows:structuredClone(rows),settings:{...settings}};}
function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function current(){return {question:$('#question').value,answer:$('#answer').value,fact_id:$('#fact-id').value,category:$('#category').value,source:$('#source').value};}
function counters(){const r=current(),n=r.question.length+1+r.answer.length;$('#q-count').textContent=r.question.length+' / 72 characters';$('#q-count').classList.toggle('over',r.question.length>72);$('#context-count').textContent=n+' / 128 context characters (includes separator)';$('#context-count').classList.toggle('over',n>128);$('#record-errors').textContent=analyze([r]).issues[0].join(' · ');}
function reset(){editing=null;$('#record-form').reset();$('#editor-title').textContent='Add a record';$('#save-record').textContent='Add record';$('#cancel-edit').hidden=true;$('#record-errors').textContent='';$('#q-count').textContent='0 / 72 characters';$('#context-count').textContent='1 / 128 context characters';}
function render(){const report=analyze(rows);$('#summary').replaceChildren();for(const [value,label] of [[rows.length,'Total records'],[report.valid,'Ready records'],[report.invalid,'Need attention'],[report.categories,'Categories']]){const d=document.createElement('div'),s=document.createElement('strong'),t=document.createElement('span');s.textContent=value;t.textContent=label;d.append(s,t);$('#summary').append(d);}
let indices=rows.map((_,i)=>i);const query=$('#search').value.toLowerCase();indices=indices.filter(i=>(!query||Object.values(rows[i]).some(v=>v.toLowerCase().includes(query)))&&($('#filter').value!=='issues'||report.issues[i].length));const pages=Math.max(1,Math.ceil(indices.length/30));page=Math.min(page,pages-1);$('#record-list').replaceChildren();if(!indices.length){const p=document.createElement('p');p.className='empty';p.textContent=rows.length?'No matching records.':'Start with your own knowledge.\nAdd a question and answer, or import JSONL, JSON, or CSV.';$('#record-list').append(p);}
for(const i of indices.slice(page*30,page*30+30)){const r=rows[i],el=document.createElement('article');el.className='record-row';const head=document.createElement('div');head.className='row-title';const title=document.createElement('strong');title.textContent=r.question||'(empty question)';const actions=document.createElement('div');for(const [label,fn] of [['Edit',()=>{editing=i;for(const [id,k] of [['question','question'],['answer','answer'],['fact-id','fact_id'],['category','category'],['source','source']])$('#'+id).value=r[k];$('#editor-title').textContent='Edit record';$('#save-record').textContent='Save changes';$('#cancel-edit').hidden=false;counters();$('#question').focus();}],['Delete',()=>{snapshot();rows.splice(i,1);reset();persist();render();status('Record deleted. Undo is available.');}]]){const b=document.createElement('button');b.textContent=label;b.onclick=fn;actions.append(b);}head.append(title,actions);const answer=document.createElement('p');answer.textContent=r.answer;const meta=document.createElement('div');meta.className='row-meta';meta.textContent=[r.fact_id?'Fact: '+r.fact_id:'',r.category,r.source].filter(Boolean).join(' · ');el.append(head,answer,meta);if(report.issues[i].length){const p=document.createElement('div');p.className='row-issue';p.textContent=report.issues[i].join(' · ');el.append(p);}$('#record-list').append(el);}
$('#page-info').textContent=indices.length+' records · Page '+(page+1)+' / '+pages;$('#previous').disabled=page===0;$('#next').disabled=page>=pages-1;$('#undo').disabled=!undo;$('#export-data').disabled=!rows.length||!!report.invalid;preview();}
function preview(){try{const sets=split(rows,settings);$('#split-preview').textContent=Object.entries(sets).map(([k,v])=>k+': '+v.length).join(' · ');}catch(e){$('#split-preview').textContent=e.message;}}
$('#record-form').onsubmit=e=>{e.preventDefault();const r=current(),next=[...rows];if(editing===null)next.push(r);else next[editing]=r;const index=editing??next.length-1,issues=analyze(next).issues[index];if(issues.length){$('#record-errors').textContent=issues.join(' · ');return;}snapshot();rows=next;reset();persist();render();status('Record saved locally.');};for(const s of ['#question','#answer'])$(s).oninput=counters;$('#cancel-edit').onclick=reset;$('#undo').onclick=()=>{if(!undo)return;rows=undo.rows;settings=undo.settings;undo=null;for(const k of ['validation','test','seed'])$('#'+k).value=settings[k];reset();persist();render();status('Last change undone.');};
for(const k of ['validation','test','seed'])$('#'+k).oninput=()=>{settings={validation:Number($('#validation').value),test:Number($('#test').value),seed:$('#seed').value};persist();preview();};
$('#search').oninput=()=>{page=0;render();};$('#filter').onchange=()=>{page=0;render();};$('#previous').onclick=()=>{page--;render();};$('#next').onclick=()=>{page++;render();};
$('#import').onclick=()=>$('#import-file').click();$('#import-file').onchange=async()=>{const f=$('#import-file').files[0];if(!f)return;try{if(f.size>10*1024*1024)throw Error('Import limit is 10 MB per file.');const ext=f.name.split('.').pop().toLowerCase(),text=await f.text(),incoming=parse(text,ext);if(incoming.length+rows.length>50000)throw Error('This workspace supports up to 50,000 records.');let importedSettings=null;if(ext==='json'){const project=JSON.parse(text);if(!Array.isArray(project)&&project.settings&&!rows.length){const proposed={validation:project.settings.validation,test:project.settings.test,seed:project.settings.seed};if(typeof proposed.seed!=='string')throw Error('Project split seed must be text.');split([],proposed);importedSettings=proposed;}}snapshot();rows.push(...incoming);if(importedSettings){settings=importedSettings;for(const k of ['validation','test','seed'])$('#'+k).value=settings[k];}reset();page=0;persist();render();status('Imported '+incoming.length+' records. Review flagged rows before export. Imports append to your current workspace.');}catch(e){status('Import failed: '+e.message);}finally{$('#import-file').value='';}};
$('#backup').onclick=()=>download('webtiny-dataset-project.json',JSON.stringify({version:1,settings,records:rows},null,2));$('#export-data').onclick=()=>{try{const files=bundle(rows,settings);download('webtiny-training-data.zip',zip(files),'application/zip');status('Exported training files and metadata. See README.txt inside the ZIP for instructions.');}catch(e){status(e.message);}};render();
